const all = queries.events.data || [];
const ev = all.find(e => e.id === variables.eventId) || all.find(e => e.status === 'Live')
  || all.filter(e => e.status === 'Planning').sort((a, b) => a.event_date.localeCompare(b.event_date))[0] || all[0];
const runs = (ev?.runs || []).slice().sort((a, b) => a.time.localeCompare(b.time));
const checks = ev?.checks || [], vendors = ev?.vendors || [];
return {
  id: ev?.id, reference: ev?.reference, status: ev?.status, name: ev?.name, venue: ev?.venue, client: ev?.client,
  event_date: ev?.event_date, producer: ev?.producer,
  runs: runs.slice(0, 4).map(r => ({ time: r.time, title: r.title, status: r.status, meta: (r.owner || '') + ' · ' + (r.required ? 'Required' : 'Optional') })),
  runsCount: runs.length,
  checksDone: checks.filter(c => c.done).length, checksTotal: checks.length,
  vendorsConfirmed: vendors.filter(v => v.status === 'Confirmed').length, vendorsTotal: vendors.length,
  blockers: checks.filter(c => c.required && !c.done).length + vendors.filter(v => v.required && v.status !== 'Confirmed').length,
  history: (ev?.history || []).slice().reverse()
};
